import { unlinkSync, writeFileSync } from "node:fs";

import { expect, expectStatus, sample, test, uniqueName } from "../../fixtures";

test("An expired insurance certificate cannot be approved", { tag: "@REV-07" }, async ({ apiAs, factory }) => {
  // Arrange
  const reviewer = await apiAs("reviewer");
  // The API compares expiry against the UTC date (utcnow().date()), so "yesterday" is in UTC.
  const yesterday = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString().slice(0, 10);
  const file = `${uniqueName("insurance-expired").replace(/\s+/g, "-")}.txt`;
  writeFileSync(
    sample(file),
    `Insurer: Harbor Mutual\nPolicy Number: HM-55-1290\nCoverage Amount: $2,000,000\nExpiry Date: ${yesterday}\n`,
  );
  try {
    const { extractions } = await factory.vendorInReview({ files: { insurance_certificate: file } });

    // Act
    const response = await reviewer.post(`/api/extractions/${extractions.insurance_certificate.id}/decision`, {
      data: { decision: "approve" },
    });

    // Assert
    const body = await expectStatus(response, 409);
    expect(body.error.code).toBe("insurance_expired");
  } finally {
    unlinkSync(sample(file));
  }
});
